return items.flatMap(item => {
  const mensagens = item.json.data || [];

  return mensagens.map(msg => {
    let nomeCliente = null;

    // Extrair nome do cliente a partir da mensagem padrão
    if (typeof msg.mensagem === 'string') {
      const match = msg.mensagem.match(/Olá\s+([^,]+),/i);
      if (match) {
        nomeCliente = match[1].trim();
      }
    }

    return {
      json: {
        id: msg._id,
        rota: msg.id_rota,
        atendimento: msg.id_atend || null,
        usuario: msg.id_user || null,

        tipo: msg.tipo,
        mensagem: msg.mensagem,

        nome_cliente: nomeCliente,

        canal: msg.canalComunicacao,
        origem: msg.origin,
        destinatario: msg.destinatario,
        tipoDestinatario: msg.tipoDestinatario,

        data: msg.data,
        criadoEm: msg.createdAt,
        atualizadoEm: msg.updatedAt,

        visivelParaContato: msg.visivelParaContato,
        statusLeitura: msg.statusEnvio?.status || null,

        mensagemCanalId: msg.idMensagemCanal || null,
        mensagemCitataId: msg.id_mensagem_citada || null
      }
    };
  });
});

