const items = $input.all();
const seen = new Set();
const out = [];

for (const item of items) {
  let data = item.json.data;

  // 1) parseia se vier como string
  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch (e) {
      continue; // ignora se não der parse
    }
  }

  // 2) pega registros
  const registros = data?.registros;
  if (!Array.isArray(registros)) continue;

  // 3) deduplica
  for (const r of registros) {
    const key = r?.id; // 👈 chave de duplicação (9778)

    if (!key) continue;
    if (seen.has(key)) continue;

    seen.add(key);

    out.push({
      json: r
    });
  }
}

return out;

// --- Helpers ---------------------------------------------------------------

// Decodifica entidades HTML comuns (inclui numéricas: &#225; / &#xE1;)
function decodeHtml(str = "") {
  if (!str || typeof str !== "string") return "";
  const map = {
    "&nbsp;": " ", "&amp;": "&", "&lt;": "<", "&gt;": ">",
    "&quot;": '"', "&apos;": "'",
    "&aacute;": "á", "&eacute;": "é", "&iacute;": "í", "&oacute;": "ó", "&uacute;": "ú",
    "&Aacute;": "Á", "&Eacute;": "É", "&Iacute;": "Í", "&Oacute;": "Ó", "&Uacute;": "Ú",
    "&atilde;": "ã", "&otilde;": "õ", "&Atilde;": "Ã", "&Otilde;": "Õ",
    "&acirc;": "â", "&ecirc;": "ê", "&icirc;": "î", "&ocirc;": "ô", "&ucirc;": "û",
    "&Acirc;": "Â", "&Ecirc;": "Ê", "&Icirc;": "Î", "&Ocirc;": "Ô", "&Ucirc;": "Û",
    "&ccedil;": "ç", "&Ccedil;": "Ç",
    "&ouml;": "ö", "&Ouml;": "Ö", "&uuml;": "ü", "&Uuml;": "Ü",
  };
  str = str.replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)));
  str = str.replace(/&#x([0-9a-fA-F]+);/g, (_, n) => String.fromCharCode(parseInt(n, 16)));
  return str.replace(/&[a-zA-Z]+;/g, m => map[m] || m);
}

// Extrai com regex: retorna grupo 1 ou null
function pick(re, s) {
  const m = s.match(re);
  return m ? m[1].trim() : null;
}

// Converte número (ex.: "-23.76") => Number ou null
function toNum(v) {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(String(v).replace(",", "."));
  return Number.isFinite(n) ? n : null;
}

// Normaliza HTML -> texto
function htmlToText(html = "") {
  return decodeHtml(
    String(html)
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/div>/gi, "\n")
      .replace(/<[^>]+>/g, " ")
  )
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n[ \t]+/g, "\n")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/\n{2,}/g, "\n")
    .trim();
}

// Extrai campos do texto
function parseONU(text) {
  const tituloPainel   = pick(/^\s*(Pot[êe]ncia de ONU)\s*$/mi, text) || "Potência de ONU";

  const causaUltQueda  = pick(/Causa da .*?queda:\s*([^\n]+)/i, text);
  const sinalRx        = toNum(pick(/Sinal\s*Rx:\s*([-\d.,]+)/i, text));
  const temperatura    = toNum(pick(/Temperatura:\s*([-\d.,]+)/i, text));
  const voltagem       = toNum(pick(/Voltagem:\s*([-\d.,]+)/i, text));
  const sinalTx        = toNum(pick(/Sinal\s*Tx:\s*([-\d.,]+)/i, text));
  const statusPotencia = pick(/Status\s*pot[êe]ncia:\s*([^\n]+)/i, text);

  const fs_p           = pick(/F\/s\/p:\s*([^\n]+)/i, text);
  const onuId          = pick(/Onu id:\s*([^\n]+)/i, text);
  const controlFlag    = pick(/Control flag:\s*([^\n]+)/i, text);
  const runState       = pick(/Run state:\s*([^\n]+)/i, text);
  const configState    = pick(/Config state:\s*([^\n]+)/i, text);

  const downTime       = pick(/Down time:\s*([^\n]+)/i, text);
  const lastDyingGasp  = pick(/Last .*?gasp time:\s*([^\n]+)/i, text);
  const onlineDuration = pick(/Online duration:\s*([^\n]+)/i, text);

  const macRouter      = pick(/Mac router:\s*([0-9A-Fa-f:]+)/i, text);
  const vendorSn       = pick(/Vendor sn:\s*([^\n]*)/i, text) || null;

  const txOlt          = toNum(pick(/Tx olt:\s*([-\d.,]+)/i, text));
  const rxOlt          = toNum(pick(/Rx olt:\s*([-\d.,]+)/i, text));

  return {
    titulo: tituloPainel,
    causa_ultima_queda: causaUltQueda,
    status_potencia: statusPotencia,

    medidas: {
      sinal_rx_dbm: sinalRx,
      sinal_tx_dbm: sinalTx,
      temperatura_c: temperatura,
      voltagem_v: voltagem,
      tx_olt: txOlt,
      rx_olt: rxOlt,
    },

    operacao: {
      fs_p,
      onu_id: onuId,
      control_flag: controlFlag,
      run_state: runState,
      config_state: configState,
      down_time: downTime,
      last_dying_gasp_time: lastDyingGasp,
      online_duration: onlineDuration,
    },

    rede: {
      mac_router: macRouter,
      vendor_sn: vendorSn,
    },
  };
}

