// parse seguro do campo data (pode vir string JSON)
function parseData(v) {
  if (!v) return {};
  if (typeof v === 'object') return v;
  if (typeof v !== 'string') return {};
  try { return JSON.parse(v); } catch (e) { return {}; }
}

// controle de duplicados
const seen = new Set();

// 1) filtra somente os que vieram com total = 0 (sem info no IXC)
//    + remove duplicados
const vazios = items.filter(it => {
  const d = parseData(it.json?.data);
  const total = Number(d?.total ?? 0);

  if (total !== 0) return false;

  // 🔑 chave de deduplicação
  const key = it.json?.id_cliente || it.json?.login;
  if (!key) return false;

  if (seen.has(key)) return false;
  seen.add(key);

  return true;
});

// 2) se não tiver nenhum, retorna msg ok
