  const j = it.json || {};
  const idCliente = j.id_cliente ?? "-";
  const login = j.login ?? "-";
  const idContrato = j.id_contrato ?? "-";

  return `${i + 1}) id_cliente: ${idCliente} | login: ${login} | contrato: ${idContrato}`;
});

